#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const int INF = 0x3f3f3f3f;
const int MAX_N = 210;

struct Edge {
    int to, w, next;
} edges[MAX_N * MAX_N];

const int DIRS[4][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

int n, t, source, sink, capacities[15][15], sciences[15][15], maze[65][15][15], head[MAX_N], edgeCount;
bool visited[15][15], reachable[65][15][15][15][15];

void addEdge(int u, int v, int w) {
    edges[edgeCount] = {v, w, head[u]};
    head[u] = edgeCount++;
    edges[edgeCount] = {u, 0, head[v]};
    head[v] = edgeCount++;
}

int dist[MAX_N], current[MAX_N];

bool bfs(int s, int t) {
    memset(dist, 0, sizeof(dist));
    queue<int> q;
    q.push(s);
    current[s] = head[s];
    dist[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; ~i; i = edges[i].next) {
            int v = edges[i].to, w = edges[i].w;
            if (dist[v] || !w) continue;
            dist[v] = dist[u] + 1;
            current[v] = head[v];
            q.push(v);
            if (v == t) return true;
        }
    }
    return false;
}

int dfs(int u, int t, int flow) {
    if (u == t) return flow;
    int rest = flow, i;
    for (i = current[u]; ~i && rest; i = edges[i].next) {
        int v = edges[i].to, w = edges[i].w;
        if (w && dist[v] == dist[u] + 1) {
            int pushed = dfs(v, t, min(rest, w));
            if (!pushed) dist[v] = 0;
            edges[i].w -= pushed;
            edges[i ^ 1].w += pushed;
            rest -= pushed;
        }
    }
    current[u] = i;
    return flow - rest;
}

int maxFlow(int s, int t) {
    int result = 0, flow;
    while (bfs(s, t))
        while ((flow = dfs(s, t, INF)))
            result += flow;
    return result;
}

int getId(int x, int y, int k) {
    return (x - 1) * n + y + k * n * n;
}

void dfsReach(int startX, int startY, int curX, int curY, int step) {
    visited[curX][curY] = true;
    reachable[step][startX][startY][curX][curY] = true;
    if (step >= t || maze[step][curX][curY]) return;
    for (int d = 0; d < 4; ++d) {
        int nx = curX + DIRS[d][0], ny = curY + DIRS[d][1];
        if (nx < 1 || ny < 1 || nx > n || ny > n) continue;
        if (visited[nx][ny] || maze[step][nx][ny]) continue;
        dfsReach(startX, startY, nx, ny, step + 1);
    }
}

void preprocess() {
    memset(current, 0, sizeof(current));
    memset(head, -1, sizeof(head));
    edgeCount = 0;
    for (int timeStep = 1; timeStep <= t; ++timeStep) {
        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                if (maze[timeStep - 1][x][y])
                    maze[timeStep][x][y] = maze[timeStep - 1][x][y];
                else {
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + DIRS[d][0], ny = y + DIRS[d][1];
                        if (nx < 1 || ny < 1 || nx > n || ny > n) continue;
                        if (maze[timeStep - 1][nx][ny] == 2)
                            maze[timeStep][x][y] = 2;
                    }
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (sciences[i][j]) {
                memset(visited, false, sizeof(visited));
                dfsReach(i, j, i, j, 0);
            }
        }
    }
    for (int step = 1; step <= t; ++step)
        for (int x = 1; x <= n; ++x)
            for (int y = 1; y <= n; ++y)
                for (int xx = 1; xx <= n; ++xx)
                    for (int yy = 1; yy <= n; ++yy)
                        reachable[step][x][y][xx][yy] |= reachable[step - 1][x][y][xx][yy];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> t;
    for (int i = 1; i <= n; ++i) {
        string line;
        cin >> line;
        for (int j = 1; j <= n; ++j) {
            char c = line[j - 1];
            if (isdigit(c)) sciences[i][j] = c - '0';
            else if (c == 'Y') maze[0][i][j] = 1;
            else if (c == 'Z') maze[0][i][j] = 2;
        }
    }
    for (int i = 1; i <= n; ++i) {
        string line;
        cin >> line;
        for (int j = 1; j <= n; ++j) {
            char c = line[j - 1];
            if (isdigit(c)) capacities[i][j] = c - '0';
        }
    }
    source = n * n * 2;
    sink = source - 1;
    preprocess();
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (sciences[i][j]) addEdge(source, getId(i, j, 0), sciences[i][j]);
            if (capacities[i][j]) addEdge(getId(i, j, 1), sink, capacities[i][j]);
        }
    }
    for (int x = 1; x <= n; ++x)
        for (int y = 1; y <= n; ++y)
            for (int xx = 1; xx <= n; ++xx)
                for (int yy = 1; yy <= n; ++yy)
                    if (sciences[x][y] && capacities[xx][yy] && reachable[t][x][y][xx][yy])
                        addEdge(getId(x, y, 0), getId(xx, yy, 1), INF);
    cout << maxFlow(source, sink) << '\n';
    return 0;
}
